// Golden tests: the cabinet engine must reproduce the prototype exactly. The fixtures were
// generated by running the unchanged prototype (scripts/prototype-fixtures.mjs).
import { describe, expect, it } from 'vitest';
import fixtures from './fixtures/prototype-cabinets.json';
import { buildCabinet } from '../src/cabinets/build';
import { cabinetSettings, DEFAULT_CABINET_SETTINGS, type CabinetSettings } from '../src/cabinets/settings';
import type { CabinetInput } from '../src/cabinets/types';

/** Rounds every number to 1e-9 so the comparison ignores floating-point noise only. */
export function settle(v: unknown): unknown {
  if (typeof v === 'number') return Math.round(v * 1e9) / 1e9 + 0;
  if (Array.isArray(v)) return v.map(settle);
  if (v && typeof v === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, x] of Object.entries(v)) if (x !== undefined) out[k] = settle(x);
    return out;
  }
  return v;
}

describe('cabinet settings', () => {
  it('match the prototype defaults', () => {
    const { slideLens, grainFree: _g, leftLen: _1, rightLen: _2, stoveWall: _3, stoveFrom: _4, stoveW: _5, winWall: _6, winFrom: _7, winW: _8, cornerOwner: _9, ...rest } =
      fixtures.defaults as Record<string, unknown>;
    expect({ ...rest, slideLengths: String(slideLens).split(/[,\s]+/).map(Number) }).toEqual({ ...DEFAULT_CABINET_SETTINGS });
  });
});

describe('cabinet engine matches the prototype', () => {
  for (const k of fixtures.cases) {
    it(k.name, () => {
      const settings = cabinetSettings((k as { settings?: Partial<CabinetSettings> }).settings);
      const got = buildCabinet(k.input as CabinetInput, settings, 'X1');
      expect(settle(got)).toEqual(settle(k.expected));
    });
  }
});
